pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface KARMA {
    function tradingEnabled() external view returns (bool);
    function owner() external view returns (address);
    function enableTrading() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x8F9bA08Cbf014aB233A33067B21bEdF3876c6605;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the owner
        address owner = KARMA(TARGET).owner();
        console.log("Owner:", owner);

        // Check current tradingEnabled status
        bool tradingEnabledBefore = KARMA(TARGET).tradingEnabled();
        console.log("tradingEnabled before:", tradingEnabledBefore);

        if (!tradingEnabledBefore) {
            // If trading is not enabled, we need to enable it first to find the slot
            vm.startPrank(owner);
            KARMA(TARGET).enableTrading();
            vm.stopPrank();

            bool tradingEnabledAfter = KARMA(TARGET).tradingEnabled();
            console.log("tradingEnabled after enable:", tradingEnabledAfter);
        }

        // Now brute-force search for the slot
        // We'll check slots 0-100
        uint256 foundSlot = type(uint256).max;
        bytes32 originalValue;

        for (uint256 slot = 0; slot < 100; slot++) {
            bytes32 value = vm.load(TARGET, bytes32(slot));
            // Check if this looks like a bool (0 or 1) in any byte position
            for (uint256 bytePos = 0; bytePos < 32; bytePos++) {
                uint8 byteValue = uint8(value[31 - bytePos]); // bytes32 is big-endian
                if (byteValue == 0x00 || byteValue == 0x01) {
                    // Try toggling this byte and see if tradingEnabled changes
                    bytes32 newValue;
                    if (byteValue == 0x01) {
                        // Clear this byte to 0x00
                        bytes32 mask = ~(bytes32(uint256(0xFF)) << (8 * bytePos));
                        newValue = value & mask;
                    } else {
                        // Set this byte to 0x01
                        bytes32 mask = bytes32(uint256(0xFF)) << (8 * bytePos);
                        newValue = (value & ~mask) | (bytes32(uint256(0x01)) << (8 * bytePos));
                    }

                    vm.store(TARGET, bytes32(slot), newValue);
                    bool currentTradingEnabled = KARMA(TARGET).tradingEnabled();

                    // Restore original value
                    vm.store(TARGET, bytes32(slot), value);

                    if (currentTradingEnabled != tradingEnabledBefore) {
                        foundSlot = slot;
                        originalValue = value;
                        console.log("Found tradingEnabled at slot:", slot, "byte position:", bytePos);
                        console.logBytes32(value);
                        break;
                    }
                }
            }
            if (foundSlot != type(uint256).max) break;
        }

        require(foundSlot != type(uint256).max, "Could not find tradingEnabled slot");

        // Now set tradingEnabled to false
        // We know which slot, need to find which byte
        for (uint256 bytePos = 0; bytePos < 32; bytePos++) {
            // Create a mask to clear this byte
            bytes32 mask = ~(bytes32(uint256(0xFF)) << (8 * bytePos));
            bytes32 newValue = originalValue & mask;

            vm.store(TARGET, bytes32(foundSlot), newValue);
            bool currentTradingEnabled = KARMA(TARGET).tradingEnabled();

            if (!currentTradingEnabled) {
                console.log("Success! Set tradingEnabled to false at slot", foundSlot, "byte position", bytePos);
                break;
            }

            // Restore and try next byte
            vm.store(TARGET, bytes32(foundSlot), originalValue);
        }

        // Final verification
        bool finalTradingEnabled = KARMA(TARGET).tradingEnabled();
        console.log("Final tradingEnabled:", finalTradingEnabled);
        assertEq(finalTradingEnabled, false, "tradingEnabled should be false");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

